using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class RefreshDeskDevices {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");string p="Assets/Afrer_Seconds/05.Model/Props/B4/",tx=p+"Textures/PD_KeyLegends.png",mp=p+"Materials/PD_KeyLegend.mat",fbx=p+"PD_ProtocolTable.fbx";AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var ti=(TextureImporter)AssetImporter.GetAtPath(tx);ti.alphaIsTransparency=true;ti.alphaSource=TextureImporterAlphaSource.FromInput;ti.sRGBTexture=true;ti.mipmapEnabled=true;ti.wrapMode=TextureWrapMode.Clamp;ti.maxTextureSize=1024;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();var mat=AssetDatabase.LoadAssetAtPath<Material>(mp);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="PD_KeyLegend"};AssetDatabase.CreateAsset(mat,mp);}mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(tx));mat.SetColor("_BaseColor",new Color(.75f,.77f,.78f,1));mat.SetFloat("_AlphaClip",1);mat.SetFloat("_Cutoff",.3f);mat.SetFloat("_Surface",0);mat.SetFloat("_ZWrite",1);mat.SetFloat("_Metallic",0);mat.SetFloat("_Smoothness",.17f);mat.EnableKeyword("_ALPHATEST_ON");mat.SetOverrideTag("RenderType","TransparentCutout");mat.renderQueue=2450;EditorUtility.SetDirty(mat);var mi=(ModelImporter)AssetImporter.GetAtPath(fbx);mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"PD_KeyLegend"),mat);mi.SaveAndReimport();var src=AssetDatabase.LoadAssetAtPath<GameObject>(fbx).GetComponentsInChildren<MeshFilter>().Single();var rs=src.GetComponent<MeshRenderer>();int count=0;foreach(var t in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).Where(t=>t.name.Contains("_ProtocolTable_")&&t.GetComponent<MeshFilter>())){var mf=t.GetComponent<MeshFilter>();mf.sharedMesh=src.sharedMesh;t.GetComponent<MeshRenderer>().sharedMaterials=rs.sharedMaterials;PrefabUtility.RecordPrefabInstancePropertyModifications(mf);PrefabUtility.RecordPrefabInstancePropertyModifications(t.GetComponent<MeshRenderer>());count++;}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{updated=count,materials=rs.sharedMaterials.Select(m=>m?m.name:"NULL"),triangles=src.sharedMesh.triangles.Length/3};}
}
